import{_ as a,o as i,c as o,a2 as n}from"./chunks/framework.CqpfiAoK.js";const m=JSON.parse('{"title":"Ética y Límites del Cultivo","description":"","frontmatter":{},"headers":[],"relativePath":"es/0019-修炼伦理与边界.md","filePath":"es/0019-修炼伦理与边界.md"}'),s={name:"es/0019-修炼伦理与边界.md"};function l(t,e,d,c,r,u){return i(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="etica-y-limites-del-cultivo" tabindex="-1">Ética y Límites del Cultivo <a class="header-anchor" href="#etica-y-limites-del-cultivo" aria-label="Permalink to &quot;Ética y Límites del Cultivo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Elemento</th><th>Contenido</th></tr></thead><tbody><tr><td>N.º de documento</td><td>19</td></tr><tr><td>Módulo</td><td>Leyes Cósmicas y Sistemas de Cultivo</td></tr><tr><td>Palabras clave</td><td>Ética del Cultivo, Límites, Tabúes, Línea de Fondo Moral, Revisión Ética</td></tr></tbody></table><h2 id="i-definicion-y-estatus-de-la-etica-del-cultivo" tabindex="-1">I. Definición y Estatus de la Ética del Cultivo <a class="header-anchor" href="#i-definicion-y-estatus-de-la-etica-del-cultivo" aria-label="Permalink to &quot;I. Definición y Estatus de la Ética del Cultivo&quot;">​</a></h2><p>La ética del cultivo es la suma de las normas morales y legales en la Civilización Simbiótica del Ancla que regulan la conducta de los cultivadores, delimitan los límites del cultivo y mantienen el orden del cultivo. En la era del depredacionismo, el cultivo era considerado un &quot;privilegio de los fuertes&quot;, y los cultivadores podían recurrir a cualquier medio para aumentar su poder — devorar el Origen de otros, esclavizar las almas de otros, saquear los recursos de otros, realizar experimentos de cultivo inhumanos, etc. Esta cultura de cultivo de &quot;el poder por encima de todo, la ética como nada&quot; es la raíz espiritual más profunda del sistema depredacionista.</p><p>Tras el establecimiento de la Civilización Simbiótica del Ancla, la construcción de la ética del cultivo fue convertida en una de las construcciones más centrales de la civilización espiritual. La proposición central de la ética del cultivo es: &quot;La adquisición y el uso del poder deben estar limitados por la ética.&quot; La civilización simbiótica sostiene que el cultivo no es un asunto puramente personal, sino un asunto público que involucra a otros, involucra a la civilización, involucra al cosmos en su conjunto. Mientras persiguen la elevación de su propio poder, los cultivadores deben respetar los derechos de los demás, mantener el orden de la civilización y proteger la ecología del cosmos. La ética del cultivo no es una atadura para el cultivo, sino una guardiana del cultivo — asegura que el cultivo camine siempre por el camino correcto de la &quot;evolución simbiótica&quot; y nunca se deslice hacia el abismo de la &quot;destrucción depredadora&quot;.</p><p>La ética del cultivo ocupa un estatus elevado en el sistema legal de la civilización simbiótica. La Constitución Simbiótica estipula explícitamente los principios básicos de la ética del cultivo; el Tribunal de Anclas tiene un &quot;Tribunal de Ética&quot; especializado para juzgar los casos de ética del cultivo; la certificación de niveles de todos los cultivadores avanzados debe pasar por una revisión ética. La ética del cultivo no es una &quot;restricción blanda&quot; opcional, sino una &quot;norma dura&quot; con fuerza obligatoria.</p><h2 id="ii-principios-basicos-de-la-etica-del-cultivo" tabindex="-1">II. Principios Básicos de la Ética del Cultivo <a class="header-anchor" href="#ii-principios-basicos-de-la-etica-del-cultivo" aria-label="Permalink to &quot;II. Principios Básicos de la Ética del Cultivo&quot;">​</a></h2><h3 id="_2-1-principio-de-dignidad-de-la-vida" tabindex="-1">2.1 Principio de Dignidad de la Vida <a class="header-anchor" href="#_2-1-principio-de-dignidad-de-la-vida" aria-label="Permalink to &quot;2.1 Principio de Dignidad de la Vida&quot;">​</a></h3><p>Toda vida posee dignidad y valor inviolables, y ninguna conducta de cultivo puede hacerse a costa de dañar la dignidad de la vida. Específicamente:</p><ul><li>Prohibido utilizar otras vidas como &quot;materiales&quot; o &quot;herramientas&quot; del cultivo</li><li>Prohibidos los experimentos de cultivo inhumanos (como vivisección, tortura de almas, etc.)</li><li>Prohibido esclavizar o controlar el libre albedrío de otras vidas</li><li>Respetar el derecho de toda vida a elegir su propio camino evolutivo, y no forzar a otros a cultivar según la propia manera</li></ul><h3 id="_2-2-principio-antidepredacionista" tabindex="-1">2.2 Principio Antidepredacionista <a class="header-anchor" href="#_2-2-principio-antidepredacionista" aria-label="Permalink to &quot;2.2 Principio Antidepredacionista&quot;">​</a></h3><p>El cultivo debe basarse en la circulación simbiótica, y no debe usar el saqueo de otros como medio. Específicamente:</p><ul><li>Prohibido devorar o saquear el Origen, la energía o la fortuna de otras vidas</li><li>Prohibido aumentar la propia velocidad o nivel de cultivo dañando a otros</li><li>Prohibido monopolizar los recursos de cultivo para obtener ganancias indebidas</li><li>Prohibido usar &quot;el fuerte devora al débil&quot; como excusa para justificar conductas depredadoras</li></ul><h3 id="_2-3-principio-de-consentimiento-informado" tabindex="-1">2.3 Principio de Consentimiento Informado <a class="header-anchor" href="#_2-3-principio-de-consentimiento-informado" aria-label="Permalink to &quot;2.3 Principio de Consentimiento Informado&quot;">​</a></h3><p>Las conductas de cultivo que involucran a otros (como la transmisión maestro-discípulo, el cultivo dual de parejas, el intercambio de energía, los experimentos de cultivo, etc.) deben realizarse sobre la premisa de que la otra parte está plenamente informada y consiente voluntariamente. Específicamente:</p><ul><li>Explicar plenamente a la otra parte el contenido, los riesgos y los beneficios de la conducta de cultivo</li><li>Asegurar que la otra parte tenga plena capacidad de juicio independiente, libre de coerción o seducción</li><li>La otra parte tiene derecho a retirarse en cualquier momento, y no debe ser forzada a continuar</li><li>Para menores o individuos con discapacidad mental, sus tutores ejercen el derecho de consentimiento en su nombre sobre la base de una evaluación profesional</li></ul><h3 id="_2-4-principio-de-dano-minimo" tabindex="-1">2.4 Principio de Daño Mínimo <a class="header-anchor" href="#_2-4-principio-de-dano-minimo" aria-label="Permalink to &quot;2.4 Principio de Daño Mínimo&quot;">​</a></h3><p>Las conductas de cultivo deben evitar dañar a otros y al entorno tanto como sea posible. Cuando algún impacto es inevitable, debe elegirse el método menos dañino y debe hacerse una compensación razonable por el daño causado. Específicamente:</p><ul><li>Los experimentos de cultivo deben realizarse prioritariamente en el Espacio de Aislamiento, evitando la difusión de riesgos</li><li>El cultivo de combate debe realizarse en recintos dedicados tanto como sea posible, evitando daños al entorno público</li><li>La contaminación energética, los daños espaciales, etc. generados durante el cultivo deben limpiarse y repararse oportunamente</li><li>Prohibidas las actividades de cultivo de alto riesgo en zonas densamente pobladas</li></ul><h3 id="_2-5-principio-de-honestidad-y-no-engano" tabindex="-1">2.5 Principio de Honestidad y No Engaño <a class="header-anchor" href="#_2-5-principio-de-honestidad-y-no-engano" aria-label="Permalink to &quot;2.5 Principio de Honestidad y No Engaño&quot;">​</a></h3><p>Los cultivadores deben permanecer honestos en los asuntos relacionados con el cultivo y no deben cometer fraude. Específicamente:</p><ul><li>Prohibido falsificar niveles de cultivo, valores de contribución, resultados de exámenes, etc.</li><li>Prohibido el fraude o el plagio en las percepciones de cultivo y los resultados de investigación</li><li>Prohibido proporcionar información falsa en solicitudes de recursos y declaraciones de proyectos</li><li>Prohibido usar falsas promesas para defraudar a otros de sus recursos de cultivo o de su confianza</li></ul><h3 id="_2-6-principio-de-responsabilidad" tabindex="-1">2.6 Principio de Responsabilidad <a class="header-anchor" href="#_2-6-principio-de-responsabilidad" aria-label="Permalink to &quot;2.6 Principio de Responsabilidad&quot;">​</a></h3><p>Cuanto mayor es el poder, mayor es la responsabilidad. Los cultivadores avanzados deben asumir responsabilidades públicas acordes con su poder. Específicamente:</p><ul><li>Los cultivadores que alcanzan cierto nivel tienen la obligación de guiar a los cultivadores principiantes</li><li>Los cultivadores avanzados tienen la obligación de participar en asuntos públicos como el mantenimiento de anclas y la guardia de la civilización</li><li>Los cultivadores asumen la responsabilidad por las consecuencias de sus propias conductas de cultivo, sin eludirla</li><li>Cuando la civilización enfrenta una crisis, los cultivadores avanzados tienen la obligación de dar un paso al frente</li></ul><h2 id="iii-tabues-absolutos-del-cultivo" tabindex="-1">III. Tabúes Absolutos del Cultivo <a class="header-anchor" href="#iii-tabues-absolutos-del-cultivo" aria-label="Permalink to &quot;III. Tabúes Absolutos del Cultivo&quot;">​</a></h2><p>Las siguientes conductas constituyen los &quot;tabúes absolutos&quot; del cultivo; ningún cultivador puede tocarlas bajo ninguna circunstancia, y los infractores enfrentarán las sanciones más severas:</p><table tabindex="0"><thead><tr><th>Tipo de Tabú</th><th>Conducta Específica</th><th>Medidas de Sanción</th></tr></thead><tbody><tr><td>Saqueo del Origen</td><td>Devorar o saquear el Origen o el núcleo vital de otras vidas</td><td>Abolición del cultivo, prisión perpetua, aniquilación del Origen para casos graves</td></tr><tr><td>Esclavitud de Almas</td><td>Convertir otras vidas en herramientas mediante control de almas, esclavitud espiritual, etc.</td><td>Abolición del cultivo, reeducación ética obligatoria, privación permanente del derecho de cultivo</td></tr><tr><td>Genocidio Racial</td><td>Masacre o exterminio sistemático de una raza con fines de cultivo</td><td>Juicio supremo del Tribunal de Anclas, pena capital</td></tr><tr><td>Destrucción de Planos</td><td>Destruir un plano entero para obtener recursos o poder</td><td>Pena capital, y plena responsabilidad por la restauración del plano</td></tr><tr><td>Experimentos Inhumanos</td><td>Realizar experimentos de cultivo inhumanos sobre vidas inteligentes</td><td>Abolición del cultivo, prisión perpetua, destrucción de todos los resultados de investigación</td></tr><tr><td>Crimen Temporal</td><td>Usar la capacidad de regresión temporal para falsificación histórica o asesinato a gran escala</td><td>Pena capital, y privación permanente de las capacidades relacionadas con el tiempo</td></tr><tr><td>Contaminación de Leyes</td><td>Contaminar deliberadamente las leyes del Origen cósmico, causando daños irreversibles al cosmos en su conjunto</td><td>Pena capital, y purificación de leyes ejecutada por el máximo órgano de la civilización</td></tr></tbody></table><p>El establecimiento de los tabúes absolutos encarna la postura firme de la civilización simbiótica sobre la línea de fondo de la ética del cultivo. Estos tabúes no tienen &quot;zona gris&quot;, no tienen &quot;circunstancias atenuantes&quot;; cualquier conducta que toque los tabúes absolutos enfrentará las sanciones más severas.</p><h2 id="iv-zonas-grises-de-la-etica-del-cultivo-y-principios-de-tratamiento" tabindex="-1">IV. Zonas Grises de la Ética del Cultivo y Principios de Tratamiento <a class="header-anchor" href="#iv-zonas-grises-de-la-etica-del-cultivo-y-principios-de-tratamiento" aria-label="Permalink to &quot;IV. Zonas Grises de la Ética del Cultivo y Principios de Tratamiento&quot;">​</a></h2><p>Además de las prohibiciones claras, existen algunas &quot;zonas grises&quot; en la ética del cultivo — estas conductas no son en sí mismas absolutamente buenas o malas; su naturaleza ética depende de la situación, el motivo, el método y las consecuencias específicas. Para las zonas grises, la civilización simbiótica adopta los siguientes principios de tratamiento:</p><h3 id="_4-1-zonas-grises-comunes" tabindex="-1">4.1 Zonas Grises Comunes <a class="header-anchor" href="#_4-1-zonas-grises-comunes" aria-label="Permalink to &quot;4.1 Zonas Grises Comunes&quot;">​</a></h3><ul><li><strong>Daño en el cultivo de combate</strong>: los cultivadores pueden dañarse mutuamente en el entrenamiento de combate; si este daño es ético depende de si ambas partes dieron consentimiento informado y de si el daño está dentro de un rango razonable</li><li><strong>Competencia por recursos</strong>: si la competencia entre cultivadores por recursos raros es ética depende de si el método de competencia es justo y de si se respetan las reglas antimonopolio</li><li><strong>Asimetría de poder en la relación maestro-discípulo</strong>: existe naturalmente una asimetría de poder entre maestro y discípulo; si el maestro abusa del poder requiere un juicio específico</li><li><strong>Asunción de riesgos en el cultivo</strong>: algunos métodos de cultivo conllevan altos riesgos; si la asunción voluntaria de riesgos por un cultivador es ética requiere evaluar el conocimiento informado del riesgo y la disponibilidad de alternativas</li><li><strong>Cooperación de cultivo entre razas</strong>: la cooperación entre diferentes razas puede implicar diferencias culturales y asimetrías de poder, requiriendo una evaluación específica</li></ul><h3 id="_4-2-principios-de-tratamiento" tabindex="-1">4.2 Principios de Tratamiento <a class="header-anchor" href="#_4-2-principios-de-tratamiento" aria-label="Permalink to &quot;4.2 Principios de Tratamiento&quot;">​</a></h3><p>Para los problemas éticos de las zonas grises, la civilización simbiótica adopta el método de tratamiento de &quot;análisis de situación específica + evaluación del comité de ética + guía de precedentes&quot;:</p><ol><li><strong>Análisis de situación específica</strong>: sin enfoque &quot;talla única&quot;; juicio integral según la situación, el motivo, el método y las consecuencias específicas</li><li><strong>Evaluación del comité de ética</strong>: para problemas éticos complejos, sometimiento al &quot;Comité de Ética&quot; dependiente del Tribunal de Anclas para evaluación profesional</li><li><strong>Guía de precedentes</strong>: los resultados de evaluación del Comité de Ética forman precedentes, proporcionando guía para casos similares posteriores</li><li><strong>Educación prioritaria</strong>: para conductas inapropiadas en zonas grises, la educación y la corrección son prioritarias sobre las sanciones severas directas</li><li><strong>Ajuste dinámico</strong>: con el desarrollo de la civilización y la profundización de la comprensión ética, los criterios de juicio de las zonas grises pueden ajustarse dinámicamente</li></ol><h2 id="v-educacion-e-internalizacion-de-la-etica-del-cultivo" tabindex="-1">V. Educación e Internalización de la Ética del Cultivo <a class="header-anchor" href="#v-educacion-e-internalizacion-de-la-etica-del-cultivo" aria-label="Permalink to &quot;V. Educación e Internalización de la Ética del Cultivo&quot;">​</a></h2><p>El mantenimiento de la ética del cultivo no puede depender solo de sanciones y supervisión externas; requiere más bien que los cultivadores se identifiquen con ella y la internalicen desde lo más profundo. La civilización simbiótica ha establecido un sistema sistemático de educación ética del cultivo:</p><h3 id="_5-1-educacion-basica" tabindex="-1">5.1 Educación Básica <a class="header-anchor" href="#_5-1-educacion-basica" aria-label="Permalink to &quot;5.1 Educación Básica&quot;">​</a></h3><ul><li>La ética del cultivo es un curso obligatorio para todos los cultivadores; la educación ética sistemática debe comenzar desde la Percepción del Origen</li><li>El contenido educativo incluye principios éticos, listas de tabúes, análisis de casos, simulación de situaciones, etc.</li><li>Los métodos educativos incluyen enseñanza en aula, discusión de casos, juegos de rol, enseñanza mediante precepto y ejemplo de los mentores, etc.</li></ul><h3 id="_5-2-educacion-avanzada" tabindex="-1">5.2 Educación Avanzada <a class="header-anchor" href="#_5-2-educacion-avanzada" aria-label="Permalink to &quot;5.2 Educación Avanzada&quot;">​</a></h3><ul><li>A medida que se elevan los niveles de los cultivadores, la profundidad y amplitud de la educación ética se elevan correspondientemente</li><li>Los cultivadores avanzados necesitan aprender problemas éticos más complejos (como ética entre planos, ética del tiempo, ética de la creación de mundos, etc.)</li><li>Los cultivadores por encima del Dao del Origen necesitan aprobar la &quot;Evaluación Ética Avanzada&quot; antes de continuar elevando sus niveles</li></ul><h3 id="_5-3-practica-e-internalizacion" tabindex="-1">5.3 Práctica e Internalización <a class="header-anchor" href="#_5-3-practica-e-internalizacion" aria-label="Permalink to &quot;5.3 Práctica e Internalización&quot;">​</a></h3><ul><li>Alentar a los cultivadores a practicar los principios éticos en el cultivo diario, transformando los requisitos éticos en hábitos de conducta conscientes</li><li>Establecer el sistema de selección de &quot;Modelos Éticos&quot;, reconociendo a los cultivadores con desempeño sobresaliente en ética del cultivo</li><li>Los mentores tienen la obligación de transmitir el espíritu ético mientras enseñan las habilidades de cultivo, logrando &quot;transmitir tanto el Dao como el arte&quot;</li></ul><h2 id="vi-supervision-y-ejecucion-de-la-etica-del-cultivo" tabindex="-1">VI. Supervisión y Ejecución de la Ética del Cultivo <a class="header-anchor" href="#vi-supervision-y-ejecucion-de-la-etica-del-cultivo" aria-label="Permalink to &quot;VI. Supervisión y Ejecución de la Ética del Cultivo&quot;">​</a></h2><h3 id="_6-1-mecanismos-de-supervision" tabindex="-1">6.1 Mecanismos de Supervisión <a class="header-anchor" href="#_6-1-mecanismos-de-supervision" aria-label="Permalink to &quot;6.1 Mecanismos de Supervisión&quot;">​</a></h3><ul><li><strong>Monitoreo de la red de anclas</strong>: la red de anclas monitorea continuamente las conductas de cultivo de los cultivadores, proporcionando alertas oportunas ante posibles violaciones éticas</li><li><strong>Sistema de denuncia ética</strong>: cualquier vida puede denunciar violaciones de la ética del cultivo ante el Tribunal de Ética del Tribunal de Anclas, y los denunciantes están protegidos</li><li><strong>Evaluación ética periódica</strong>: los cultivadores que alcanzan la Ley del Origen y superiores deben someterse a una evaluación ética cada año, con los resultados registrados en sus expedientes personales de cultivo</li><li><strong>Supervisión de organizaciones sociales</strong>: se alienta a las organizaciones de cultivadores, comunidades raciales, etc. a realizar supervisión interna de la ética del cultivo de sus miembros</li></ul><h3 id="_6-2-mecanismos-de-ejecucion" tabindex="-1">6.2 Mecanismos de Ejecución <a class="header-anchor" href="#_6-2-mecanismos-de-ejecucion" aria-label="Permalink to &quot;6.2 Mecanismos de Ejecución&quot;">​</a></h3><ul><li><strong>Tribunal de Ética</strong>: el Tribunal de Anclas tiene un Tribunal de Ética especializado responsable de juzgar los casos de ética del cultivo</li><li><strong>Sanciones graduadas</strong>: según la gravedad de las violaciones éticas, se aplican sanciones graduadas, desde advertencias, multas, deducción de valores de contribución, restricción de permisos de cultivo, abolición del cultivo, hasta prisión perpetua y pena capital</li><li><strong>Reeducación ética</strong>: para los infractores con voluntad de arrepentimiento, puede realizarse una reeducación ética junto con las sanciones; tras el éxito, algunos derechos pueden restaurarse parcialmente</li><li><strong>Antecedentes penales</strong>: los registros de violaciones de la ética del cultivo se consignan permanentemente en los expedientes personales, afectando la certificación de niveles, la distribución de recursos, las solicitudes de cargos públicos, etc.</li></ul><h2 id="vii-expansion-dinamica-de-los-limites-del-cultivo" tabindex="-1">VII. Expansión Dinámica de los Límites del Cultivo <a class="header-anchor" href="#vii-expansion-dinamica-de-los-limites-del-cultivo" aria-label="Permalink to &quot;VII. Expansión Dinámica de los Límites del Cultivo&quot;">​</a></h2><p>La ética y los límites del cultivo no son dogmas inmutables, sino normas vivas que se ajustan dinámicamente con el desarrollo de la civilización, el progreso tecnológico y la profundización de la comprensión. La civilización simbiótica ha establecido un mecanismo de expansión dinámica de los límites del cultivo:</p><ol><li><strong>Evaluación ética de nuevas tecnologías</strong>: cada vez que surge una nueva tecnología de cultivo o aplicación de leyes, se realiza primero una evaluación ética; la promoción se permite solo tras aprobar la evaluación</li><li><strong>Discusión ética de nuevos escenarios</strong>: cuando la civilización entra en nuevas etapas de desarrollo (como la era entre planos, la era interestelar, etc.), se organizan discusiones éticas especiales para formular normas éticas adaptadas a los nuevos escenarios</li><li><strong>Revisión periódica de las normas éticas</strong>: las normas específicas de la ética del cultivo se revisan cada cincuenta años, con el proceso de revisión recogiendo ampliamente las opiniones de todas las vidas</li><li><strong>Acumulación continua de precedentes éticos</strong>: las sentencias del Tribunal de Ética forman precedentes, enriqueciendo y precisando continuamente las connotaciones específicas de la ética del cultivo</li></ol><h2 id="conclusion" tabindex="-1">Conclusión <a class="header-anchor" href="#conclusion" aria-label="Permalink to &quot;Conclusión&quot;">​</a></h2><p>La ética y los límites del cultivo son el pilar central de la civilización espiritual de la Civilización Simbiótica del Ancla. Responden a una pregunta fundamental: &quot;¿Qué tipo de persona debe llegar a ser un cultivador?&quot; La respuesta de la civilización simbiótica es: un cultivador debe llegar a ser una persona con poder y, aún más, con moralidad; una persona en la que la evolución personal y la simbiosis de las Diez Mil Razas estén unificadas; una persona que persigue el poder pero que jamás es esclavizada por él. La ética del cultivo no es una atadura para el poder, sino una sublimación del poder — asegura que el poder sirva siempre a la dignidad de la vida y al progreso de la civilización, y nunca se convierta en un instrumento de destrucción y saqueo. En un cosmos donde el poder puede mover montañas y mares, puede crear mundos y destruir mundos, la ética del cultivo es la última y más importante línea de defensa que guarda la línea de fondo de la civilización.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>04-反掠夺主义核心论纲 (Tesis Centrales del Antidepredacionismo)</li><li>17-位面至高强者标准 (Estándares de Expertos Supremos de Planos)</li><li>48-司法体系与裁决机制 (Sistema Judicial y Mecanismo de Adjudicación)</li></ul>',56)])])}const v=a(s,[["render",l]]);export{m as __pageData,v as default};
